#!/data/data/com.termux/files/usr/bin/bash
# ChsiHook Termux 一键安装 v2.2（内嵌客户端，装完删明文）
set -e
pkg install -y nodejs-lts
npm install -g bytenode
mkdir -p ~/chsi && cd ~/chsi
echo '' | base64 -d | gunzip > client.js
node -e "require('bytenode').compileFile({filename:'client.js',output:'client.jsc'})"
rm -f client.js
cat > run.sh <<'EOF2'
#!/data/data/com.termux/files/usr/bin/bash
cd ~/chsi && exec node -e "require('bytenode');require('./client.jsc')" 2>&1
EOF2
chmod +x run.sh
echo 安装完成。先启动一次: ~/chsi/run.sh （显示设备码）
echo 之后浏览器打开 http://127.0.0.1:8901 设置姓名/性别/照片/授权码
